<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { db } from '../services/db'
import { isStudyMusicEnabled, setStudyMusicPreference, stopStudyMusic } from '../services/studyMusic'
const target=ref(Number(localStorage.getItem('dailyTarget')||10)),musicEnabled=ref(isStudyMusicEnabled()),message=ref(''),error=ref(''),file=ref<HTMLInputElement>()
function save(){localStorage.setItem('dailyTarget',String(target.value));message.value='设置已保存'}
function toggleMusic(){musicEnabled.value=!musicEnabled.value;setStudyMusicPreference(musicEnabled.value);message.value=musicEnabled.value?'已开启初记与强化复习背景音乐':'已关闭初记与强化复习背景音乐'}
async function initializeStudyProgress(){error.value='';message.value='';const password=prompt('请输入初始化密码（888888）');if(password===null)return;if(password!=='888888'){error.value='密码错误，未进行任何更改';return}if(!confirm('将清空所有初记进度、强化复习组、错句、测试记录和统计，并把所有句子重置为新句。句库与句子正文会保留。确定继续？'))return;try{const now=new Date().toISOString(),sentences=await db.sentences.toArray(),metaRows=await db.meta.toArray(),resetKeys=metaRows.filter(row=>/^(initialPlan:|initialActiveGroup:|initialSession:|groupCursor:|browseCursor:|browseDraft:)/.test(row.key)).map(row=>row.key);await db.transaction('rw',[db.cardStates,db.wrongEntries,db.testRecords,db.statsDaily,db.studyGroups,db.meta],async()=>{await Promise.all([db.cardStates.clear(),db.wrongEntries.clear(),db.testRecords.clear(),db.statsDaily.clear(),db.studyGroups.clear(),db.meta.bulkDelete(resetKeys)]);await db.cardStates.bulkPut(sentences.map(sentence=>({id:`${sentence.bankId}:${sentence.id}`,bankId:sentence.bankId,sentenceId:sentence.id,mastery:'new' as const,dueAt:now,intervalDays:0,repetitions:0,ease:2.5,streak:0,attempts:0,updatedAt:now}))) });stopStudyMusic();message.value=`已重置学习进度，保留 ${sentences.length} 条句子和全部句库；页面即将刷新`;window.setTimeout(()=>window.location.reload(),700)}catch(e){error.value=e instanceof Error?`初始化失败：${e.message}`:'初始化失败'}}
async function downloadBackup(){error.value='';message.value='';try{const payload:Record<string,unknown>={format:'sentence-memory-backup',version:2,exportedAt:new Date().toISOString()};for(const name of ['banks','sentences','cardStates','testRecords','wrongEntries','statsDaily','studyGroups','meta'] as const)payload[name]=await db.table(name).toArray();const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`弘文雅思8分-备份-${new Date().toISOString().slice(0,10)}.json`;a.style.display='none';document.body.appendChild(a);a.click();a.remove();window.setTimeout(()=>URL.revokeObjectURL(url),60000);message.value='已开始导出 JSON 备份，请查看浏览器下载记录或“下载”文件夹'}catch(e){error.value=e instanceof Error?`导出失败：${e.message}`:'导出失败，请重试'}}
async function restore(event:Event){error.value='';message.value='';const input=event.target as HTMLInputElement,chosen=input.files?.[0];if(!chosen)return;try{const data=JSON.parse(await chosen.text());const required=['banks','sentences','cardStates','testRecords','wrongEntries','statsDaily','meta'];const tables=[...required,'studyGroups'];if(data.format!=='sentence-memory-backup'||![1,2].includes(data.version)||required.some(t=>!Array.isArray(data[t]))||(data.version===2&&!Array.isArray(data.studyGroups)))throw new Error('备份格式不正确或版本不支持');if(data.sentences.some((s:unknown)=>!s||typeof s!=='object'||typeof (s as {text?:unknown}).text!=='string'||new TextEncoder().encode((s as {text:string}).text).length>300))throw new Error('备份中包含超过 300 UTF-8 字节或格式无效的句子');if(!confirm('导入备份会用文件内容替换当前本地数据，是否继续？'))return;await db.transaction('rw',tables.map(t=>db.table(t)),async()=>{for(const name of tables){const table=db.table(name);await table.clear();await table.bulkPut(data[name]??[])}});message.value='恢复完成，页面将重新载入';window.location.reload()}catch(e){error.value=e instanceof Error?e.message:'恢复失败'}finally{input.value=''}}
onMounted(()=>{void db.meta.put({key:'lastOpened',value:new Date().toISOString()})})
</script>
<template><section class="section-heading"><div><span class="eyebrow">YOUR PREFERENCES</span><h2>设置与备份</h2><p>调整每天的节奏，定期导出一份本地备份。</p></div><span class="local-badge"><i></i> IndexedDB 本地存储</span></section><section class="panel settings-panel"><div class="panel-heading"><div><span class="eyebrow">DAILY RHYTHM</span><h3>每日计划</h3></div></div><div class="setting-row"><div><b>每日新句目标</b><small>复习任务不受这个目标限制</small></div><div class="setting-control"><input v-model.number="target" type="number" min="1" max="100"><span>句 / 天</span><button class="button button-dark small-button" @click="save">保存</button></div></div><div class="setting-row"><div><b>数据存储</b><small>当前数据只在此浏览器 / 桌面应用本地保存</small></div><span class="storage-chip">无需账号 · 无云同步</span></div></section><section class="panel settings-panel backup-panel"><div class="panel-heading"><div><span class="eyebrow">BACKUP & RESTORE</span><h3>备份与恢复</h3></div></div><p>导出文件包含句库、句子、复习进度、测试记录和统计。请妥善保管备份文件。</p><div class="backup-actions"><button class="button button-dark" @click="downloadBackup">↓ 导出 JSON 备份</button><label class="button button-outline">↑ 从 JSON 恢复<input ref="file" type="file" accept="application/json,.json" hidden @change="restore"></label></div><p class="field-help">恢复会替换当前全部 IndexedDB 数据；请先导出当前备份。</p></section><section class="panel music-info-panel"><div><span class="eyebrow">STUDY BACKGROUND MUSIC</span><h3>学习背景音乐</h3><p>初记与强化复习开始后播放莫扎特《A大调第11号钢琴奏鸣曲》K.331 第一乐章。可在此设置是否播放；音频由 Wikimedia Commons 在线提供，离线时无法加载。</p><small>Bernd Krueger · CC BY-SA 3.0 DE · <a href="https://commons.wikimedia.org/wiki/File:Mozart_-_Piano_Sonata_No._11_in_A_major_-_I._Andante_grazioso.ogg" target="_blank" rel="noopener noreferrer">录音来源与许可</a></small></div><button class="music-toggle" :aria-pressed="musicEnabled" @click="toggleMusic">♫ 背景音乐：{{musicEnabled?'开':'关'}}<small>{{musicEnabled?'开始学习时播放':'已关闭'}}</small></button></section><section class="panel settings-panel"><div class="panel-heading"><div><span class="eyebrow">KEYBOARD SHORTCUTS</span><h3>快捷键</h3></div></div><div class="shortcut-list"><div><span>浏览页翻面</span><kbd>Space</kbd></div><div><span>标记会背 / 模糊 / 不会</span><span><kbd>1</kbd><kbd>2</kbd><kbd>3</kbd></span></div><div><span>测试选项 / 提交 / 下一题</span><span><kbd>1–4</kbd><kbd>Enter</kbd></span></div></div></section><section class="panel reset-panel"><div><span class="eyebrow">RESET LEARNING RECORDS</span><h3>初始化学习记录</h3><p>密码保护的本机进度重置。清除初记、强化复习、错句、成绩和统计；保留句库、句子与释义。</p><small>密码：888888 · 此密码用于防止误操作，不是账户安全措施。</small></div><button class="button reset-button" @click="initializeStudyProgress">输入密码并初始化</button></section><section class="panel settings-legal"><div class="legal-copy"><span class="eyebrow">ABOUT & CONTACT</span><h3>版权与联系</h3><p class="legal-motto">路漫漫其修远兮，吾将上下而求索。</p><p>本软件由弘文于丙午年仲秋（2026年9月）制作，保留所有权利。</p><p>未经版权所有者许可，禁止用于任何商业目的。<br>任何个人均可免费用于学习用途。</p><p>祝大家学习顺利。</p><p class="telegram-title">Telegram 问题反馈</p></div><img class="legal-qr" src="/telegram-qr.png" alt="Telegram 联系二维码：Avankic Zang"></section><p v-if="message" class="toast-inline">{{message}}</p><p v-if="error" class="error-inline">{{error}}</p></template>
